/* Collaboration controls; filters never modify stored workspace records. */
(function(){'use strict';
const api=()=>window.CAGE_BACKEND,me=()=>api()?.currentMemberId?.(),profile=()=>api()?.currentProfile?.(),esc=escapeHtml;
const scopes=new Set(['projects','requests','crm','commercial']);let mine=false;const replies=new Map();
const meetingLinks=['https://meet.google.com/tai-aetz-gqe','https://meet.google.com/ise-jvne-hci','https://meet.google.com/twx-mknz-ntd'];
const ids=r=>[r?.owner,r?.lead,r?.createdBy,...(r?.team||[]),...(r?.members||[]),...(r?.collaborators||[])].filter(Boolean);
function belongs(r){return ids(r).includes(me())||ids(r).includes(profile()?.id);}
function rows(key,list){if(!mine)return list;return list.filter(r=>belongs(r)||(r.project&&belongs(projectById(r.project))));}
function opportunityMine(r){if(!mine)return true;const t=r.tracking||{};return t.owner_id===profile()?.id||(t.members||[]).includes(profile()?.id)||belongs(r)||belongs(projectById(t.links?.project))||belongs(dealById(t.links?.deal));}
function updateScope(){document.querySelectorAll('[data-work-scope]').forEach(b=>{b.setAttribute('aria-pressed',String(mine));b.textContent=mine?'My work · Q':'All company work · Q';});}
function toggleScope(){mine=!mine;updateScope();renderRequests();renderProjects();renderCRM();renderCommercial();window.dispatchEvent(new Event('cage:work-scope'));}
function memberPicker(formId,r){const form=document.getElementById(formId);if(!form)return;form.querySelector('[data-collaborator-picker]')?.remove();const checked=new Set([...(r?.team||r?.members||[]),me()]);const box=document.createElement('details');box.dataset.collaboratorPicker='';box.className='teamwork-picker field-wide';box.innerHTML=`<summary>Add members</summary><p>The creator and owner are included automatically.</p><div>${assignableTeam().map(p=>`<label><input type="checkbox" name="collaborators" value="${esc(p.id)}" ${checked.has(p.id)?'checked':''}> ${esc(p.name)}</label>`).join('')}</div>`;(form.querySelector('.form-grid')||form).append(box);}
function memberValues(data,r){return {createdBy:r?.createdBy||me(),team:[...new Set([r?.createdBy||me(),String(data.get('owner')||r?.owner||''),...data.getAll('collaborators')].filter(Boolean))]};}
function canWork(key,id){if(!api()?.isProduction())return true;return (api().collaborationAccess()?.workAccess?.[key]||[]).includes(id);}
function canThread(t){if(t.customChat||t.teamWide)return true;if(!api()?.isProduction())return true;return (api().collaborationAccess()?.chatThreads||[]).includes(t.id);}
function threadMembers(t){return [...new Set([...(t.memberIds||[]),...[t.project,t.request,t.deal,t.commercial].flatMap(ids)])];}
function groupTarget(t){if(!t||t.direct||t.teamWide)return null;if(t.customChat)return {key:'chatGroups',record:state.chatGroups.find(g=>g.id===t.id)};if(t.project)return {key:'projects',record:t.project};if(t.request)return {key:'requests',record:t.request};if(t.deal)return {key:'deals',record:t.deal};if(t.commercial)return {key:'commercialRecords',record:t.commercial};return null;}
function manages(key,r){return !!r&&(profile()?.role==='admin'||[r.createdBy,r.owner].includes(me()))&&(key!=='chatGroups'||(r.members||[]).includes(me()));}
function decorateChat(){const t=threadById(activeChatThread),target=groupTarget(t),head=document.querySelector('#chat-header-menu')||document.querySelector('#chat-header .chat-header-actions');if(head&&target&&manages(target.key,target.record)&&!head.querySelector('[data-group-members]')){const b=document.createElement('button');b.type='button';b.dataset.groupMembers='';b.textContent='Add members';head.append(b);}renderReply();}
function replyId(thread){return replies.get(thread)||null;}
function clearReply(thread){replies.delete(thread);renderReply();}
function replyMarkup(message){if(!message.replyTo)return '';const original=state.messages.find(m=>m.id===message.replyTo&&threadIdForMessage(m)===threadIdForMessage(message));if(!original)return '<div class="quoted-message">Original message unavailable</div>';return `<button type="button" class="quoted-message" data-jump-message="${esc(original.id)}"><strong>${esc(teamMember(original.sender).name)}</strong><span>${esc((original.text||original.attachment||'Voice message').slice(0,180))}</span></button>`;}
function renderReply(){let bar=document.getElementById('chat-reply-preview');if(!bar){bar=document.createElement('div');bar.id='chat-reply-preview';bar.className='chat-reply-preview';document.getElementById('chat-form').before(bar);}const original=state.messages.find(m=>m.id===replyId(activeChatThread));bar.hidden=!original;if(original)bar.innerHTML=`<div><strong>Replying to ${esc(teamMember(original.sender).name)}</strong><span>${esc((original.text||original.attachment||'Voice message').slice(0,180))}</span></div><button type="button" data-cancel-reply aria-label="Cancel reply">×</button>`;}
async function addGroupMembers(){const t=threadById(activeChatThread),target=groupTarget(t);if(!target||!manages(target.key,target.record))return;const existing=target.key==='chatGroups'?target.record.members:ids(target.record);let d=document.getElementById('teamwork-members-dialog');if(!d){d=document.createElement('dialog');d.id='teamwork-members-dialog';d.className='app-dialog';document.body.append(d);}d.innerHTML=`<form><div class="dialog-heading"><h2>Add group members</h2><button type="button" data-cancel-members aria-label="Close">×</button></div><p>New members can read the group's existing messages.</p><div class="teamwork-member-list">${assignableTeam().filter(p=>!existing.includes(p.id)).map(p=>`<label><input type="checkbox" name="member" value="${esc(p.id)}"> ${esc(p.name)}</label>`).join('')||'<p>All staff are already members.</p>'}</div><p role="alert" class="form-error"></p><div class="dialog-actions"><button type="button" data-cancel-members>Cancel</button><button class="primary-button">Add members</button></div></form>`;d.querySelectorAll('[data-cancel-members]').forEach(b=>b.onclick=()=>d.close());d.querySelector('form').onsubmit=async e=>{e.preventDefault();const members=new FormData(e.currentTarget).getAll('member');if(!members.length){d.querySelector('[role=alert]').textContent='Select at least one colleague.';return;}const b=e.submitter;b.disabled=true;try{await api().collaborationRpc('collaboration_add_members',{collection:target.key,record_id:target.record.id,member_ids:members});d.close();renderChat();showToast('Members added.');}catch(error){d.querySelector('[role=alert]').textContent=error.message;}finally{b.disabled=false;}};d.showModal();}
function readOnly(container,allowed){if(!container)return;container.querySelectorAll('button,input,select,textarea').forEach(el=>{if(el.matches(allowed))return;el.disabled=true;el.title='Read-only company view';});}
function applyAccess(){const staff=profile()?.active&&profile()?.role!=='shared';document.querySelectorAll('#new-project-button,#project-form button.primary-button').forEach(b=>{b.disabled=!staff;delete b.dataset.accessDisabled;});document.querySelectorAll('[data-work-scope]').forEach(b=>{b.disabled=false;delete b.dataset.accessDisabled;});if(api()?.isProduction()){
 const project=projectById(activeProjectId);if(project&&(!canWork('projects',project.id)||api().moduleLevel('projects')!=='edit'))readOnly(document.getElementById('project-dialog-content'),'[data-close-project-workspace],[data-project-tab],[data-view-document],[data-preview-project-file],[data-refresh-project-files]');
 const request=requestById(activeRequestId);if(request&&(!canWork('requests',request.id)||api().moduleLevel('requests')!=='edit'))readOnly(document.getElementById('request-detail-content'),'[data-close-request-detail],[data-project-detail],[data-view-document]');
 document.querySelectorAll('[data-request-stage]').forEach(el=>{if(!canWork('requests',el.dataset.requestStage)||api().moduleLevel('requests')!=='edit')el.disabled=true;});
 document.querySelectorAll('[data-commercial-stage]').forEach(el=>{if(!canWork('commercialRecords',el.dataset.commercialStage)||api().moduleLevel('commercial')!=='edit')el.disabled=true;});
 document.querySelectorAll('[data-deal-card]').forEach(card=>{if(!canWork('deals',card.dataset.dealCard)||api().moduleLevel('crm')!=='edit'){card.draggable=false;readOnly(card,'[data-project-detail]');}});
}
document.querySelectorAll('[data-add-project-member],[data-remove-project-member]').forEach(b=>{const r=projectById(b.dataset.addProjectMember||b.dataset.removeProjectMember);b.disabled=!manages('projects',r)||api().moduleLevel('projects')!=='edit';});}
// Put the existing emoji picker directly next to the composer, including on mobile.
const emoji=document.getElementById('chat-emoji');if(emoji){document.getElementById('chat-attach').after(emoji);emoji.className='messenger-icon';emoji.textContent='☺';emoji.title='Add emoji';document.getElementById('chat-form').classList.add('has-direct-emoji');}
for(const view of scopes){const panel=document.querySelector(`[data-view-panel="${view}"]`);if(!panel)continue;const b=document.createElement('button');b.type='button';b.className='secondary-button teamwork-scope';b.dataset.workScope='';b.title='Press Q to switch between all work and your memberships';b.onclick=toggleScope;panel.prepend(b);}updateScope();
document.addEventListener('keydown',e=>{if(e.key.toLowerCase()!=='q'||e.repeat||e.ctrlKey||e.metaKey||e.altKey||!scopes.has(activeView)||e.target.closest('input,textarea,select,[contenteditable=true],[role=textbox]')||document.querySelector('dialog[open]'))return;e.preventDefault();toggleScope();});
document.addEventListener('click',e=>{const reply=e.target.closest('[data-reply-message]');if(reply){const m=state.messages.find(x=>x.id===reply.dataset.replyMessage&&threadIdForMessage(x)===activeChatThread);if(m){replies.set(activeChatThread,m.id);renderReply();document.getElementById('chat-input').focus();}}if(e.target.closest('[data-cancel-reply]'))clearReply(activeChatThread);const jump=e.target.closest('[data-jump-message]');if(jump){const row=[...document.querySelectorAll('[data-message-id]')].find(x=>x.dataset.messageId===jump.dataset.jumpMessage);row?.scrollIntoView({block:'center'});row?.classList.add('reply-highlight');setTimeout(()=>row?.classList.remove('reply-highlight'),1800);}if(e.target.closest('[data-group-members]'))addGroupMembers();});
const rendered=window.CAGE_CHAT?.rendered;if(rendered)window.CAGE_CHAT.rendered=function(...args){rendered.apply(this,args);decorateChat();};
for(const name of ['cage:session-ready','cage:access-closed'])window.addEventListener(name,()=>{mine=false;replies.clear();updateScope();document.getElementById('teamwork-members-dialog')?.close();renderReply();applyAccess();});
// Interview video rooms use the same three choices; physical locations remain text.
const interview=document.getElementById('interview-form');
function interviewRoom(){if(!interview)return;const old=interview.elements.location,video=interview.elements.format.value==='Video';if(video&&old.tagName!=='SELECT'){const select=document.createElement('select');select.name='location';select.required=true;select.innerHTML='<option value="">Choose meeting link</option>'+meetingLinks.map((u,i)=>`<option value="${u}">Link ${i+1}</option>`).join('');old.replaceWith(select);}else if(!video&&old.tagName==='SELECT'){const input=document.createElement('input');input.name='location';input.required=true;old.replaceWith(input);}}
interview?.elements.format.addEventListener('change',interviewRoom);interview?.addEventListener('reset',()=>setTimeout(interviewRoom,0));
function quickMembers(){return `<details class="teamwork-picker"><summary>Add members</summary><div>${assignableTeam().map(p=>`<label><input type="checkbox" name="collaborators" value="${esc(p.id)}"> ${esc(p.name)}</label>`).join('')}</div></details>`;}
window.CAGE_TEAMWORK={quickMembers,rows,belongs,opportunityMine,memberPicker,memberValues,canWork,canThread,threadMembers,replyId,replyMarkup,clearReply,applyAccess,manages,meetingOptions:old=>[['','No online meeting'],...meetingLinks.map((u,i)=>[u,'Link '+(i+1)]),...(old&&!meetingLinks.includes(old)?[[old,'Existing meeting link (keep)']]:[])]};
applyAccess();if(activeView==='chat')decorateChat();
})();
